from ch34_ink import *
import json as _json
SO = {}
def orow(p, r, verdict, prose): SO[(p, r)] = (verdict, prose)

orow(305, 5, 'MATERIAL', f'AT THAT HOUR THE HOLY ONE SAID TO THE ANGEL OF DEATH: GO AND BRING ME MOSES\' SOUL. HE WENT AND STOOD BEFORE HIM — MOSES, GIVE ME YOUR SOUL; WHERE I SIT YOU HAVE NO LEAVE TO STAND, AND YOU SAY GIVE ME YOUR SOUL? HE REBUKED HIM AND HE WENT OUT IN DISGRACE; AGAIN: GO AND BRING ME HIS SOUL — HE WENT TO HIS PLACE AND SOUGHT HIM AND FOUND HIM NOT; TO THE SEA: SINCE THE DAY HE BROUGHT ISRAEL THROUGH ME I HAVE NOT SEEN HIM; TO THE MOUNTAINS AND HILLS: SINCE THE DAY ISRAEL RECEIVED THE TORAH ON MOUNT SINAI WE HAVE NOT SEEN HIM; TO GEHENNA: HIS NAME I HAVE HEARD, HIM I HAVE NOT SEEN; TO THE MINISTERING ANGELS: GO TO THE SONS OF MEN; TO ISRAEL: GOD UNDERSTANDS ITS WAY (Job 28:23), GOD HID HIM AWAY FOR THE LIFE OF THE WORLD TO COME AND NO CREATURE KNOWS OF HIM — "AND HE BURIED HIM IN THE VALLEY" (34:6). ({SP_(305, 5, "למלאך", "המות", "לך", "והבא", "לי", "נשמתו", "של")} "to the angel of death: go and bring me the soul of"; {SP_(305, 5, "אלהים", "גנזו", "לחיי", "העולם", "הבא")} "God hid him for the life of the world to come"; {SP_(305, 5, "ויקבר", "אתו", "בגיא")} "and He buried him in the valley"): THE ANGEL OF DEATH REFUSED — the piska of 31:14 ("behold, your days approach to die" — the row read at chapters 29-31; 305\'s first row opens with no citation marker, headless to the instrument) ends on 34:6: the burial by the Holy One and the grave unknown read as the HIDING of Moses for the world to come, the sea, Sinai, Gehenna, the angels and Israel the witnesses (the sea\'s crossing and Sinai on the tape — RUN CITATIONS); "by the mouth of the LORD" (34:5) and not by the angel\'s hand — Onkelos\'s Memra, the tradition\'s kiss. The compile: no law — a DATA note beside 34:6\'s grave_unknown status. DV34-03. REREAD WHOLE (chapters 29-31\'s reading — 31:14).')
orow(341, 1, 'MATERIAL', f'"FOR FROM AFAR YOU SHALL SEE THE LAND, BUT THERE YOU SHALL NOT COME" (32:52) — IT IS SAID HERE "THERE YOU SHALL NOT COME" AND IT IS SAID THERE "THERE YOU SHALL NOT CROSS OVER" (34:4); ONE CANNOT SAY "YOU SHALL NOT CROSS OVER", FOR "YOU SHALL NOT COME" IS ALREADY SAID, NOR "YOU SHALL NOT COME", FOR "YOU SHALL NOT CROSS OVER" IS ALREADY SAID — MOSES SAID BEFORE THE HOLY ONE: IF I MAY NOT ENTER AS A KING, LET ME ENTER AS A COMMONER; IF NOT ALIVE, LET ME ENTER DEAD; HE SAID TO HIM: "THERE YOU SHALL NOT COME", "THERE YOU SHALL NOT CROSS OVER" — NOT AS A KING NOR A COMMONER, NOT ALIVE NOR DEAD. ({SP_(341, 1, "נאמר", "כאן", "ושמה", "לא", "תבא", "ונאמר", "להלן")} "it is said here: there you shall not come; and it is said there"; {SP_(341, 1, "לא", "מלך", "ולא", "הדיוט", "לא", "חי", "ולא")} "not a king nor a commoner, not alive nor"): THE TWO DENIALS — 32:52\'s "come" and 34:4\'s "cross over" read as two requests refused (the king and the commoner, the living and the dead), the verbal analogy of the two "there"s (I2 — the Sifrei\'s own; the row read at the song, its twin 357:27 in the death\'s piska word for word); 34:4 cited there never read — READ HERE, the pointer 32:52 -> 34:4 paid. The compile: the denial\'s two seats one status on Moses (barred_from_the_land\'s entries unmoved — the song\'s runner read 32:52 with 34:4 cited; the readback row at 22b). DV34-02. REREAD WHOLE (the song\'s reading — 32:52).')

# ---- THE TESTING SHELF'S ONE ROW (Tosefta Sotah 4:4 — the export's Hebrew and English read whole; the cuts by consonants over the Hebrew) ----
_TH = _json.load(open(f'{ROOT}/Data/sefaria_export/Tosefta_Sotah/he.json', encoding='utf-8'))['text'][3][3]
_TE = _json.load(open(f'{ROOT}/Data/sefaria_export/Tosefta_Sotah/en.json', encoding='utf-8'))['text'][3][3]
TOS_HE = clean(_TH); TOS_EN = clean(_TE)
assert TOS_HE.startswith('משה זכה בעצמות') and TOS_EN.startswith('Moses merited the bones') and len(TOS_HE.encode()) == 2893 and len(TOS_EN.encode()) == 4650, (TOS_HE[:30], TOS_EN[:30], len(TOS_HE.encode()), len(TOS_EN.encode()))   # the measure's print
def TP_(*cons):
    ws = TOS_HE.split(); out, i = [], 0
    for k in cons:
        j = i
        while j < len(ws) and plain(ws[j]).strip('.,:;?!"()–-״׳[]\'') != k: j += 1
        if j >= len(ws): FAIL.append(('T', 4, 4, k)); out.append('⟨MISS⟩'); continue
        out.append(ws[j].rstrip('.,:;?!')); i = j + 1
    return ' '.join(out)
TO = {}
def trow(tractate, c, h, verdict, prose): TO[(tractate, c, h)] = (verdict, prose)

trow('Sotah', 4, 4, 'MATERIAL', f'MOSES MERITED JOSEPH\'S BONES; HIM NONE BUT THE PLACE, BLESSED BE HE, ATTENDED — "AND HE BURIED HIM IN THE VALLEY" (34:6): IT TEACHES THAT HE WAS BORNE IN THE BODY OF THE SHEKHINAH ABOUT FOUR MIL FROM REUBEN\'S PORTION TO GAD\'S — HE DIED IN REUBEN\'S FIELD ("THE SONS OF REUBEN BUILT" Numbers 32:37) AND WAS BURIED IN THE FIELD OF GAD\'S INHERITANCE ("HE CHOSE A FIRST PART FOR HIMSELF, FOR THERE THE LAWGIVER\'S PORTION IS HIDDEN" 33:20-21), THE MINISTERING ANGELS LAMENTING "HE EXECUTED THE RIGHTEOUSNESS OF THE LORD" (33:21); AND SO WITH THE SUSPECTED WIFE — THE THIGH WHERE THE SIN BEGAN IS STRUCK FIRST, THEN THE BELLY (Numbers 5:22, 27); SO THE FLOOD\'S MEN, SODOM\'S, EGYPT\'S GREAT ONES, THE SPIES, THE LAND\'S NEIGHBORS AND JERUSALEM\'S PROPHETS — THEY BEGAN THE SIN AND WERE STRUCK FIRST, AND THE REST DID NOT ESCAPE. ({TP_("משה", "זכה", "בעצמות")} "Moses merited the bones"; {TP_("מלמד", "שהיה", "מוטל")} "it teaches that he was borne"; {TP_("של", "שכינה", "כארבעה", "מילין", "מחלקו", "של", "ראובן")} "of the Shekhinah about four mil from the portion of Reuben"; {TP_("לחלקו", "של", "גד")} "to the portion of Gad"): THE TESTING SHELF\'S ONE ROW AT THIS READING — found beside 355:6 at the blessing and LEFT for the death\'s sitting (21b): the Tosefta\'s Sotah 4:4 (the export Tosefta_Sotah, the Vilna paragraphs — the Lieberman export\'s 4:4 is another paragraph, the quail) teaches THE FOUR MIL (355:6\'s "on the wings of the Shekhinah" — "in the body of the Shekhinah" here) with the burial by the Holy One alone (the Mishnah\'s row "Moses merited Joseph\'s bones, and none but the Place attended him" — Sotah 1:9 in the Vilna numbering, the compile\'s case: the measure-for-measure ladder of Sotah 1:7-9), Reuben\'s Nebo (Numbers 32:37-38 on the tape) and Gad\'s hidden portion (33:20-21 on the tape — 21b\'s DATA row moses_grave_ahead) — 357:31 the spine\'s own row on the two places; the row\'s second half the suspected wife\'s thigh and belly (Numbers 5 on the tape — the sotah\'s runner by CALL at 22b) and the six who began the sin. The compile: the grave\'s two tribes a DATA row (died in Reuben\'s, buried in Gad\'s — the pointer 33:21 -> 34:6 PAID), the four mil the shelf\'s datum beside 355:6\'s. DV34-03. Fresh.')
